package docsdrift

// invariants_index_test.go — the package table of docs/INVARIANTS.md is
// GENERATED by scripts/gen-invariants-index.sh from every <pkg>/INVARIANTS.md
// and <pkg>/INVARIANTS.d/ (between the BEGIN/END GENERATED markers), so a PR
// that adds or changes an invariant edits only its package's file. Before this
// the table was written by hand: concurrent PRs each edited it and the merge
// resolution kept both versions of a changed row, which left every package
// listed twice with different counts (UPGRADE-RESTORE-COMPAT-1,
// DOCS-OPS-TAILS-2) and a hand-kept Total that matched neither branch (#4237).
//
// What this checks on the real document:
//   - the generated block is up to date: the generator's own --check passes, so
//     the counts equal what the package files and fragments say (the one thing
//     the hand-kept table could never be checked for);
//   - each package appears in one row only, each row's Invariants = Guarded +
//     UNGUARDED, and there is NO Total row (the column sums are computed here
//     and logged);
//   - every row's linked file exists and is the row's own package's
//     INVARIANTS.md;
//   - every line of the counts table (the "| Package |" header through the last
//     consecutive "|" line) is the header, the separator or a package row: any
//     other line is reported, because a row the patterns do not match would
//     otherwise be left out of the sums without a word;
//   - the marker pair is present once, in order, and no package row or Total row
//     sits outside it (the hand-written text around the block is prose only).
//
// What it does NOT check: that the text outside the markers is unchanged from
// some earlier version (it is hand-written; the generator's calibration test
// proves the generator itself never alters it), the INVARIANTS.d/ file naming
// and ID rules (internal/statemap's invariants_fragments_guard_test.go), or any
// "|" table elsewhere in the document.

import (
	"errors"
	"fmt"
	"os"
	"os/exec"
	"path/filepath"
	"regexp"
	"strconv"
	"strings"
	"testing"

	"github.com/keyorixhq/keyorix/internal/guardrules"
)

const (
	invIndexBeginMark = "<!-- BEGIN GENERATED: package table -->"
	invIndexEndMark   = "<!-- END GENERATED: package table -->"
	invIndexGenerator = "scripts/gen-invariants-index.sh"
)

var (
	// | `pkg` | [file](link) | 40 | 35 | 5 |
	invIndexRowRE = regexp.MustCompile("^\\|\\s*(`[^|]+?(?:\\s+\\(\\+[^|]*\\))?)\\s*\\|\\s*\\[[^\\]]+\\]\\([^)]+\\)\\s*\\|\\s*(\\d+)\\s*\\|\\s*(\\d+)\\s*\\|\\s*(\\d+)\\s*\\|\\s*$")
	// | **Total** | | **248** | **211** | **37** |
	invIndexTotalRE = regexp.MustCompile(`^\|\s*\*\*Total\*\*\s*\|[^|]*\|\s*\*\*(\d+)\*\*\s*\|\s*\*\*(\d+)\*\*\s*\|\s*\*\*(\d+)\*\*\s*\|\s*$`)
	// | Package | File | Invariants | Guarded | UNGUARDED |
	invIndexHeaderRE = regexp.MustCompile(`^\|\s*Package\s*\|`)
	// |---|---|---|---|---|
	invIndexSepRE = regexp.MustCompile(`^\|[\s:|-]+\|\s*$`)
	// the first backticked token of a row's package cell, and the link target
	invIndexPkgRE  = regexp.MustCompile("^\\|\\s*`([^`]+)`")
	invIndexLinkRE = regexp.MustCompile(`\]\(([^)]+)\)`)
)

// checkInvariantsIndex returns one message per problem in the index document.
func checkInvariantsIndex(doc string) []string {
	problems, _, _, _ := invariantsIndexSums(doc)
	return problems
}

// invariantsIndexSums is checkInvariantsIndex plus the column sums of the
// package rows (invariants, guarded, UNGUARDED).
func invariantsIndexSums(doc string) (problems []string, inv, guarded, unguarded int) {
	type counts struct {
		inv, guarded, unguarded, line int
		text                          string // the row as written, so a message can quote it
	}
	seen := map[string]counts{}
	var order []string
	var sum counts
	var totals []counts

	inTable := false
	for i, line := range strings.Split(doc, "\n") {
		n := i + 1
		switch {
		case invIndexHeaderRE.MatchString(line):
			inTable = true
			continue
		case inTable && !strings.HasPrefix(line, "|"):
			inTable = false
		case inTable && invIndexSepRE.MatchString(line):
			continue
		}
		if m := invIndexTotalRE.FindStringSubmatch(line); m != nil {
			c := counts{line: n, text: line}
			c.inv, _ = strconv.Atoi(m[1])
			c.guarded, _ = strconv.Atoi(m[2])
			c.unguarded, _ = strconv.Atoi(m[3])
			totals = append(totals, c)
			continue
		}
		m := invIndexRowRE.FindStringSubmatch(line)
		if m == nil {
			if inTable {
				problems = append(problems, fmt.Sprintf("line %d: table row matches neither the package-row nor the Total pattern, so it is not counted: %q", n, line))
			}
			continue
		}
		pkg := strings.TrimSpace(m[1])
		c := counts{line: n, text: line}
		c.inv, _ = strconv.Atoi(m[2])
		c.guarded, _ = strconv.Atoi(m[3])
		c.unguarded, _ = strconv.Atoi(m[4])
		if first, dup := seen[pkg]; dup {
			problems = append(problems, fmt.Sprintf("line %d: package %s is listed twice: the table is generated, so rerun %s (on a merge conflict take main's file first)\n  line %d: %s\n  line %d: %s", n, pkg, invIndexGenerator, first.line, first.text, n, line))
		} else {
			seen[pkg] = c
			order = append(order, pkg)
		}
		if c.inv != c.guarded+c.unguarded {
			problems = append(problems, fmt.Sprintf("line %d: %s has %d invariants but %d guarded + %d UNGUARDED", n, pkg, c.inv, c.guarded, c.unguarded))
		}
		sum.inv += c.inv
		sum.guarded += c.guarded
		sum.unguarded += c.unguarded
	}

	if len(order) == 0 {
		return append(problems, "no package rows found: the row pattern no longer matches the table"), sum.inv, sum.guarded, sum.unguarded
	}
	// The table carries NO total (#4237). Two PRs that each touched the Total
	// row, or each appended a package row above it, merged in the queue into two
	// Total rows or a sum that matched neither PR, so a PR that was green on its
	// own branch failed on the merge result. The sums are derived here from the
	// rows instead and logged by the test; the generator never writes a Total.
	for _, t := range totals {
		problems = append(problems, fmt.Sprintf("line %d: remove the Total row (%s): the table has none, the sums are computed by this test from the package rows, currently %d / %d / %d (invariants / guarded / UNGUARDED); a hand-kept row is what made concurrent PRs fail each other in the merge queue (#4237)",
			t.line, t.text, sum.inv, sum.guarded, sum.unguarded))
	}
	return problems, sum.inv, sum.guarded, sum.unguarded
}

// invariantsIndexMarkerProblems checks the marker pair and that nothing that
// looks like a package or Total row sits outside it. Rows outside the block
// would be hand-kept duplicates of generated ones.
func invariantsIndexMarkerProblems(doc string) []string {
	var problems []string
	begin, end := -1, -1
	nBegin, nEnd := 0, 0
	lines := strings.Split(doc, "\n")
	for i, line := range lines {
		switch line {
		case invIndexBeginMark:
			nBegin++
			if begin < 0 {
				begin = i
			}
		case invIndexEndMark:
			nEnd++
			if end < 0 {
				end = i
			}
		}
	}
	if nBegin != 1 || nEnd != 1 {
		return append(problems, fmt.Sprintf("want exactly one %q and one %q line, found %d and %d", invIndexBeginMark, invIndexEndMark, nBegin, nEnd))
	}
	if begin > end {
		return append(problems, fmt.Sprintf("the END GENERATED marker (line %d) comes before the BEGIN marker (line %d)", end+1, begin+1))
	}
	for i, line := range lines {
		if i > begin && i < end {
			continue
		}
		if invIndexRowRE.MatchString(line) || invIndexTotalRE.MatchString(line) {
			problems = append(problems, fmt.Sprintf("line %d: a table row outside the generated block (the table is generated: do not hand-keep rows next to it): %q", i+1, line))
		}
	}
	return problems
}

// invariantsIndexRowFileProblems checks every package row's link: the target
// must exist under root and be the row's own package's INVARIANTS.md.
func invariantsIndexRowFileProblems(root, doc string) []string {
	var problems []string
	for i, line := range strings.Split(doc, "\n") {
		if !invIndexRowRE.MatchString(line) {
			continue
		}
		pkg := invIndexPkgRE.FindStringSubmatch(line)
		link := invIndexLinkRE.FindStringSubmatch(line)
		if pkg == nil || link == nil {
			problems = append(problems, fmt.Sprintf("line %d: cannot read the package or link of row %q", i+1, line))
			continue
		}
		target := filepath.Clean(filepath.Join(root, "docs", filepath.FromSlash(link[1])))
		if _, err := os.Stat(target); err != nil {
			problems = append(problems, fmt.Sprintf("line %d: the file of row `%s` does not exist: %s (%v)", i+1, pkg[1], link[1], err))
		}
		if want := "../" + pkg[1] + "/INVARIANTS.md"; link[1] != want {
			problems = append(problems, fmt.Sprintf("line %d: row `%s` links %s, want %s", i+1, pkg[1], link[1], want))
		}
	}
	return problems
}

// runInvIndexGen runs the generator against root with the given extra args and
// returns its combined output and exit code. A failure to start it at all is
// fatal: never skipped, the check would otherwise silently not run.
func runInvIndexGen(t testing.TB, root string, env []string, args ...string) (string, int) {
	t.Helper()
	script := filepath.Join(repoRoot(t), filepath.FromSlash(invIndexGenerator))
	cmd := exec.Command("bash", append([]string{script, "--root", root}, args...)...)
	cmd.Env = append(os.Environ(), env...)
	out, err := cmd.CombinedOutput()
	if err == nil {
		return string(out), 0
	}
	var ee *exec.ExitError
	if errors.As(err, &ee) {
		return string(out), ee.ExitCode()
	}
	t.Fatalf("run %s: %v", invIndexGenerator, err)
	return "", -1
}

func TestInvariantsIndexHasNoDuplicateRowsAndTotalsAddUp(t *testing.T) {
	g := guardrules.Rollout(t)
	doc := readDoc(g, "docs/INVARIANTS.md")
	problems, inv, guarded, unguarded := invariantsIndexSums(doc)
	for _, p := range problems {
		g.Errorf("docs/INVARIANTS.md: %s", p)
	}
	for _, p := range invariantsIndexMarkerProblems(doc) {
		g.Errorf("docs/INVARIANTS.md: %s", p)
	}
	// The diagnostic a failing queue run needs: the exact sums of the tree this
	// ran on, so a mismatch is visible without re-deriving it.
	t.Logf("docs/INVARIANTS.md package rows sum to %d / %d / %d (invariants / guarded / UNGUARDED)", inv, guarded, unguarded)
}

// TestInvariantsIndexBlockIsGenerated is the freshness guard: the block must be
// exactly what the generator writes for this tree. The failure message is the
// generator's own diff plus the one-line fix.
func TestInvariantsIndexBlockIsGenerated(t *testing.T) {
	g := guardrules.Rollout(t)
	out, code := runInvIndexGen(g, repoRoot(g), nil, "--check")
	if code != 0 {
		g.Errorf("docs/INVARIANTS.md package table is not what %s generates (exit %d): run %s and commit docs/INVARIANTS.md (never edit the block by hand; on a merge conflict take main's file, then rerun it)\n%s",
			invIndexGenerator, code, invIndexGenerator, out)
	}
}

// TestInvariantsIndexRowsPointAtRealFiles: every row's file exists and is its
// own package's INVARIANTS.md.
func TestInvariantsIndexRowsPointAtRealFiles(t *testing.T) {
	g := guardrules.Rollout(t)
	for _, p := range invariantsIndexRowFileProblems(repoRoot(g), readDoc(g, "docs/INVARIANTS.md")) {
		g.Errorf("docs/INVARIANTS.md: %s", p)
	}
}

// TestInvariantsIndexCheck_Calibration proves checkInvariantsIndex fires on
// each defect it names and stays silent on a clean table.
func TestInvariantsIndexCheck_Calibration(t *testing.T) {
	const head = "| Package | File | Invariants | Guarded | UNGUARDED |\n|---|---|---|---|---|\n"
	rowA := "| `a/core` | [a/INVARIANTS.md](../a/INVARIANTS.md) | 10 | 8 | 2 |\n"
	rowB := "| `b/http` (+ `handlers`) | [b/INVARIANTS.md](../b/INVARIANTS.md) | 5 | 5 | 0 |\n"
	rowA2 := "| `a/core` | [a/INVARIANTS.md](../a/INVARIANTS.md) | 11 | 8 | 3 |\n"
	total := "| **Total** | | **15** | **13** | **2** |\n"

	cases := []struct {
		name string
		doc  string
		want string // substring of the single expected problem; "" = clean
	}{
		{"clean", head + rowA + rowB, ""},
		{"duplicate package row", head + rowA + rowB + rowA2, "listed twice"},
		{"row does not add up", head + rowA + "| `b/http` | [b](../b) | 5 | 4 | 0 |\n", "5 invariants but 4 guarded"},
		{"total row, even a correct one", head + rowA + rowB + total, "remove the Total row"},
		{"two totals", head + rowA + rowB + total + total, "remove the Total row"},
		{"no rows", "# empty\n", "no package rows found"},
	}
	for _, tc := range cases {
		got := checkInvariantsIndex(tc.doc)
		switch {
		case tc.want == "" && len(got) != 0:
			t.Errorf("%s: want clean, got %v", tc.name, got)
		case tc.want == "":
		case tc.name == "two totals" && (len(got) != 2 || !strings.Contains(got[0], tc.want) || !strings.Contains(got[1], tc.want)):
			t.Errorf("%s: want one problem per Total row containing %q, got %v", tc.name, tc.want, got)
		case tc.name != "two totals" && (len(got) != 1 || !strings.Contains(got[0], tc.want)):
			t.Errorf("%s: want one problem containing %q, got %v", tc.name, tc.want, got)
		}
	}

	// The sums are derived from the rows, whatever order PRs landed them in.
	_, inv, guarded, unguarded := invariantsIndexSums(head + rowA + rowB)
	if inv != 15 || guarded != 13 || unguarded != 2 {
		t.Errorf("sums = %d / %d / %d, want 15 / 13 / 2", inv, guarded, unguarded)
	}
	_, inv2, guarded2, unguarded2 := invariantsIndexSums(head + rowB + rowA)
	if inv != inv2 || guarded != guarded2 || unguarded != unguarded2 {
		t.Errorf("sums depend on row order: %d / %d / %d vs %d / %d / %d", inv, guarded, unguarded, inv2, guarded2, unguarded2)
	}
}

// TestInvariantsIndexMarkerAndRowFileChecks_Calibration proves the marker, the
// rows-outside-the-block and the row-file checks fire on each defect and stay
// silent on a clean document.
func TestInvariantsIndexMarkerAndRowFileChecks_Calibration(t *testing.T) {
	root := t.TempDir()
	if err := os.MkdirAll(filepath.Join(root, "docs"), 0o755); err != nil {
		t.Fatal(err)
	}
	if err := os.MkdirAll(filepath.Join(root, "a"), 0o755); err != nil {
		t.Fatal(err)
	}
	if err := os.WriteFile(filepath.Join(root, "a", "INVARIANTS.md"), []byte("x\n"), 0o644); err != nil {
		t.Fatal(err)
	}
	const head = "| Package | File | Invariants | Guarded | UNGUARDED |\n|---|---|---|---|---|\n"
	rowA := "| `a` | [a/INVARIANTS.md](../a/INVARIANTS.md) | 1 | 1 | 0 |\n"
	rowGone := "| `gone` | [gone/INVARIANTS.md](../gone/INVARIANTS.md) | 1 | 1 | 0 |\n"
	rowWrongLink := "| `a` | [a/INVARIANTS.md](../a/OTHER.md) | 1 | 1 | 0 |\n"
	block := func(rows string) string {
		return "prose\n" + invIndexBeginMark + "\n" + head + rows + invIndexEndMark + "\nmore prose\n"
	}

	markers := []struct {
		name, doc, want string
	}{
		{"clean", block(rowA), ""},
		{"no markers", "prose\n" + head + rowA, "exactly one"},
		{"no end marker", "prose\n" + invIndexBeginMark + "\n" + head + rowA, "exactly one"},
		{"two begin markers", invIndexBeginMark + "\n" + block(rowA), "exactly one"},
		{"end before begin", invIndexEndMark + "\n" + head + rowA + invIndexBeginMark + "\n", "comes before"},
		{"row after the block", block(rowA) + rowA, "outside the generated block"},
		{"row before the block", rowA + block(rowA), "outside the generated block"},
		{"total after the block", block(rowA) + "| **Total** | | **1** | **1** | **0** |\n", "outside the generated block"},
	}
	for _, tc := range markers {
		got := invariantsIndexMarkerProblems(tc.doc)
		switch {
		case tc.want == "" && len(got) != 0:
			t.Errorf("markers/%s: want clean, got %v", tc.name, got)
		case tc.want != "" && (len(got) != 1 || !strings.Contains(got[0], tc.want)):
			t.Errorf("markers/%s: want one problem containing %q, got %v", tc.name, tc.want, got)
		}
	}

	files := []struct {
		name, doc, want string
	}{
		{"clean", block(rowA), ""},
		{"missing file", block(rowGone), "does not exist"},
		{"link is not the row's own package", block(rowWrongLink), "want ../a/INVARIANTS.md"},
	}
	for _, tc := range files {
		got := invariantsIndexRowFileProblems(root, tc.doc)
		switch {
		case tc.want == "" && len(got) != 0:
			t.Errorf("row files/%s: want clean, got %v", tc.name, got)
		case tc.want != "":
			found := false
			for _, p := range got {
				found = found || strings.Contains(p, tc.want)
			}
			if !found {
				t.Errorf("row files/%s: want a problem containing %q, got %v", tc.name, tc.want, got)
			}
		}
	}
}
